function setupPwaInstallSection(){const sec=el('pwa-install-section'),ios=el('pwa-ios-instructions'),and=el('pwa-android-instructions'),btn=el('btn-install-pwa');if(!sec||!ios||!and||!btn)return;if(window.matchMedia('(display-mode: standalone)').matches||window.navigator.standalone){sec.classList.add('hidden');return;}sec.classList.remove('hidden');if(/iphone|ipad|ipod/.test(window.navigator.userAgent.toLowerCase())){ios.classList.remove('hidden');and.classList.add('hidden');}else{ios.classList.add('hidden');and.classList.remove('hidden');btn.onclick=async()=>{if(deferredPrompt){deferredPrompt.prompt();const{outcome}=await deferredPrompt.userChoice;if(outcome==='accepted')sec.classList.add('hidden');deferredPrompt=null;}else showToast('info','כדי להתקין, פתחו את תפריט הדפדפן ובחרו התקן.');};}}

