function showToast(t,m){const tm=el('toast'),ic=el('toast-icon');if(!tm||!ic)return;tm.classList.remove('hidden');el('toast-message').innerText=m;ic.className=t==='success'?'fa-solid fa-check text-green-400':'fa-solid fa-xmark text-red-400';setTimeout(()=>tm.classList.add('hidden'),3000);}
function toggleLoader(a,s){const tx=el(`btn-${a}-text`),ld=el(`btn-${a}-loader`);if(tx&&ld){tx.classList.toggle('hidden',s);ld.classList.toggle('hidden',!s);}}
function triggerConfetti(){if(typeof confetti!=='undefined')confetti({particleCount:100,spread:70,origin:{y:0.6}});}
function triggerShake(){const a=el('main-wrapper');if(a){a.classList.add('shake-effect');setTimeout(()=>a.classList.remove('shake-effect'),500);}}
function toggleFab(){const fc=el('fab-container');if(fc)fc.classList.toggle('fab-open');}

const hidePreloaderAndShowAuth=(view='login')=>{const a=el('auth-container');if(a)a.classList.remove('hidden');switchView(view);const p=el('app-preloader');if(p){p.classList.add('opacity-0','pointer-events-none');setTimeout(()=>p.classList.add('hidden'),700);}};

window.onload=async()=>{
    initAccessibility();
    const bM=el('btn-forecast-monthly'),bY=el('btn-forecast-yearly');if(bM)bM.addEventListener('click',()=>toggleForecastMode('monthly'));if(bY)bY.addEventListener('click',()=>toggleForecastMode('yearly'));
    const fsTimer=setTimeout(()=>{const p=el('app-preloader');if(p&&!p.classList.contains('hidden')){console.warn('Failsafe');hidePreloaderAndShowAuth('login');}},5000);
    const params=new URLSearchParams(window.location.search);const code=params.get('code'),role=params.get('role');
    if(code){if(el('join-code'))el('join-code').value=code;if(role&&el('join-role'))el('join-role').value=role;clearTimeout(fsTimer);hidePreloaderAndShowAuth('join');return;}
    const token=localStorage.getItem('ofl_sa_token');
    if(token){saToken=token;clearTimeout(fsTimer);if(el('auth-container'))el('auth-container').classList.add('hidden');if(el('sa-dashboard-container'))el('sa-dashboard-container').classList.remove('hidden');const p=el('app-preloader');if(p){p.classList.add('opacity-0','pointer-events-none');setTimeout(()=>p.classList.add('hidden'),700);}loadSAData();return;}
    const saved=localStorage.getItem('ofl_session');
    if(saved){try{const s=JSON.parse(saved);if(s&&s.user&&s.user.id){currentUser=s.user;currentGroup=s.group;clearTimeout(fsTimer);loadDashboard();return;}}catch(e){localStorage.removeItem('ofl_session');}}
    clearTimeout(fsTimer);hidePreloaderAndShowAuth('login');
};

function switchView(view){['login','create','join','sa-login'].forEach(v=>{const e=el(`view-${v}`);if(e)e.classList.add('hidden');});const t=el(`view-${view}`);if(t)t.classList.remove('hidden');}
function selectType(t){if(el('create-type'))el('create-type').value=t;if(el('type-family'))el('type-family').className=`flex-1 p-4 rounded-2xl border-2 text-center transition hover:bg-slate-50 ${t==='FAMILY'?'border-blue-500 bg-blue-50 text-blue-600 font-bold':'border-slate-100 text-slate-400 font-bold'}`;if(el('type-business'))el('type-business').className=`flex-1 p-4 rounded-2xl border-2 text-center transition hover:bg-slate-50 ${t==='BUSINESS'?'border-blue-500 bg-blue-50 text-blue-600 font-bold':'border-slate-100 text-slate-400 font-bold'}`;}
function openTosModal(e){if(e){e.preventDefault();e.stopPropagation();}const m=el('tos-modal');if(m)m.classList.remove('hidden');}
function closeTosModal(){const m=el('tos-modal');if(m)m.classList.add('hidden');}

async function handleLogin(e){e.preventDefault();forceTourStart=false;authAction('login',{groupCode:val('login-code'),nickname:val('login-nickname'),password:val('login-password')});}
async function handleCreate(e){e.preventDefault();const tos=el('create-tos');if(tos&&!tos.checked)return showToast('error','יש לאשר את התקנון');forceTourStart=true;authAction('groups',{type:val('create-type'),groupName:val('create-group-name'),adminEmail:val('create-email'),adminNickname:val('create-nickname'),birthYear:val('create-year'),password:val('create-password')});}
async function handleJoin(e){e.preventDefault();const tos=el('join-tos');if(tos&&!tos.checked)return showToast('error','יש לאשר את התקנון');forceTourStart=true;toggleLoader('join',true);try{const res=await fetch(`${API}/join`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({groupCode:val('join-code'),role:val('join-role'),nickname:val('join-nickname'),birthYear:val('join-year'),password:val('join-password')})});const d=await res.json();if(d.success){showToast('success','נשלח בהצלחה!');window.history.replaceState({},document.title,window.location.pathname);switchView('login');}else showToast('error',d.error);}catch(err){showToast('error','שגיאה');}finally{toggleLoader('join',false);}}
async function authAction(endpoint,body){toggleLoader('login',true);toggleLoader('create',true);try{const res=await fetch(`${API}/${endpoint}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await res.json();if(data.success){currentUser=data.user;currentGroup=data.group;localStorage.setItem('ofl_session',JSON.stringify({user:currentUser,group:currentGroup}));await loadDashboard();}else{showToast('error',data.error);hidePreloaderAndShowAuth('login');}}catch(e){showToast('error','שגיאה בחיבור');hidePreloaderAndShowAuth('login');}finally{toggleLoader('login',false);toggleLoader('create',false);}}
function logout(){localStorage.removeItem('ofl_session');location.reload();}
function scrollTabs(d){const sc=el('slider-scroll');if(sc)sc.scrollBy({left:d*-150,behavior:'smooth'});}

function switchTab(t){
    ['feed','timeclock','tasks','shop','bank','cashflow','academy','members','budget','pantry','recipes','forecast'].forEach(x=>{const e=el(`content-${x}`);if(e)e.classList.add('hidden');const b=el(`tab-${x}`);if(b)b.classList.remove('tab-active');});
    const cT=el(`content-${t}`);if(cT)cT.classList.remove('hidden');const tT=el(`tab-${t}`);if(tT)tT.classList.add('tab-active');
    if(t!=='shop'){const f=el('cart-footer');if(f)f.classList.add('hidden');const fc=el('fab-container');if(fc)fc.classList.remove('fab-lifted');}else{try{renderShopList();}catch(e){}}
    if(t==='pantry')renderPantry();if(t==='recipes')renderRecipePantrySelection();if(t==='forecast')renderForecast();if(t==='cashflow')renderCashflow();if(t==='timeclock')fetchTimeclockReport();
}

function updateBatteryUI(){
    const ind=el('ai-battery-indicator');if(!ind||!currentGroup)return;
    ind.classList.remove('hidden','bg-slate-100','text-slate-500','border-slate-200','bg-purple-100','text-purple-600','border-purple-200','bg-red-100','text-red-600','border-red-200','bg-slate-800','text-white','border-transparent');
    const isB=currentGroup.type==='BUSINESS';
    if(currentGroup.is_premium){ind.innerHTML=isB?'<i class="fa-solid fa-bolt"></i> ∞ (Enterprise)':'⚡ ∞ (Pro)';if(isB)ind.classList.add('bg-slate-800','text-white','border-transparent');else ind.classList.add('bg-gradient-to-r','from-indigo-500','to-purple-500','text-white','border-transparent');}
    else{const tk=currentGroup.ai_tokens!==undefined?currentGroup.ai_tokens:10;ind.innerHTML=`⚡ ${tk}/10`;if(tk>3)ind.classList.add('bg-slate-100','text-slate-600','border-slate-200');else if(tk>0)ind.classList.add('bg-orange-100','text-orange-600','border-orange-200');else ind.classList.add('bg-red-100','text-red-600','border-red-200');}
}

function handleAIResponseCheck(data){if(data.error==='BATTERY_EMPTY'){const m=el('ai-battery-modal'),u=el('ai-upgrade-section');if(u)u.classList.toggle('hidden',currentUser.role!=='ADMIN');if(m)m.classList.remove('hidden');return false;}return true;}
function closeAiBatteryModal(){const m=el('ai-battery-modal');if(m)m.classList.add('hidden');}
function executeWithAIWarning(cb){if(currentGroup&&currentGroup.is_premium)return cb();const t=new Date().toLocaleDateString(),d=localStorage.getItem('ofl_ai_warning_dismissed');if(d===t)return cb();const m=el('ai-warning-modal'),l=el('ai-warning-left');if(l)l.innerText=currentGroup.ai_tokens||10;const bc=el('btn-ai-warning-continue');if(bc){const n=bc.cloneNode(true);bc.parentNode.replaceChild(n,bc);n.onclick=()=>{const ds=el('ai-warning-dont-show');if(ds&&ds.checked)localStorage.setItem('ofl_ai_warning_dismissed',t);if(m)m.classList.add('hidden');cb();};}if(m)m.classList.remove('hidden');}
function showFamilAIModal(t,txt){const m=el('familai-advisor-modal'),s=el('familai-modal-subtitle'),l=el('familai-advisor-loading'),te=el('familai-advice-text'),c=el('familai-advisor-content');if(m)m.classList.remove('hidden');if(s)s.innerText=t;if(txt){if(l)l.classList.add('hidden');if(te)te.innerText=txt;if(c)c.classList.remove('hidden');}else{if(l)l.classList.remove('hidden');if(c)c.classList.add('hidden');}}

