function applyDynamicTerminology(){
    if(!currentGroup||currentGroup.type!=='BUSINESS')return;
    document.body.classList.add('is-business');document.title='Oneflow | מערכת ניהול לעסקים';
    const sH=(id,h)=>{if(el(id))el(id).innerHTML=h;};const sT=(id,t)=>{if(el(id))el(id).innerText=t;};
    sH('tab-shop','רכש 🛒');sH('tab-pantry','מלאי ציוד 📦');sH('tab-bank','תקציבים 💳');sH('tab-budget','בקרה תפעולית 📊');sH('tab-tasks','משימות עובדים ✅');sH('tab-academy','מרכז הכשרות 🎓');sH('tab-members','ניהול צוות 👥');
    if(el('tab-timeclock'))el('tab-timeclock').classList.remove('hidden');
    sT('balance-label','מאזן קופת הארגון');const cts=el('child-todo-section');if(cts){const h=cts.querySelector('h3');if(h)h.innerText='טיקטים ומשימות 🎯';}
    sH('req-title','<i class="fa-solid fa-hourglass-half"></i> בקשות רכש לאישור');
    BUDGET_LABELS['allowance']='💰 תקציבי עובדים';BUDGET_LABELS['tasks']='✅ בונוס טיקטים';BUDGET_LABELS['academy']='🎓 תמריצי הכשרה';
    const im=el('invite-modal');if(im){const h=im.querySelector('h3');if(h)h.innerText='הזמנת עובדים 👨‍💼';const p=im.querySelector('p');if(p)p.innerHTML=`קוד הארגון: <span id="display-group-code" class="font-mono font-bold text-slate-800 bg-slate-100 px-2 py-1 rounded tracking-widest border border-slate-200">---</span>`;const bs=im.querySelectorAll('button');if(bs.length>=2){bs[0].innerHTML='<i class="fa-solid fa-user-tie"></i> מנהל/ת (הרשאה מלאה)';bs[1].innerHTML='<i class="fa-solid fa-user"></i> איש/אשת צוות (רגיל)';}}
}

async function checkGlobalWelcome(){try{const res=await fetch(`${API}/settings/welcome`);const d=await res.json();if(d.message&&d.message.trim()!==''){const seen=localStorage.getItem(`ofl_welcome_${currentUser.id}_${currentGroup.group_code}`);if(seen!==d.message){const w=el('welcome-modal-text');if(w)w.innerText=d.message;setupPwaInstallSection();const m=el('welcome-modal');if(m)m.classList.remove('hidden');window.pendingWelcomeMsg=d.message;return true;}}}catch(e){}return false;}
