// --- ליבה מרכזית: טעינה ושליפה ---
async function loadDashboard() {
    try {
        const aC=el('auth-container'), dC=el('dashboard-container'), fC=el('fab-container');
        if(aC)aC.classList.add('hidden');if(dC)dC.classList.remove('hidden');if(fC)fC.classList.remove('hidden');
        
        const cB = currentGroup.group_code ? `<span class="text-[10px] font-mono bg-blue-100 text-blue-600 px-2 py-0.5 rounded-full mr-2 tracking-widest">קוד: ${currentGroup.group_code}</span>` : '';
        const dn=el('dash-group-name'); if(dn)dn.innerHTML=`${currentGroup.name} ${cB}`; 
        const uN=el('dash-nickname'); if(uN)uN.innerText=currentUser.nickname||'משתמש';
        
        applyDynamicTerminology();
        const isAdm=currentUser.role==='ADMIN', isBiz=currentGroup.type==='BUSINESS';

        if(isAdm) {
            ['admin-panel','btn-add-task','budget-filter','bank-admin-view','academy-admin-view','btn-scan-receipt','admin-shop-tools','btn-budget-insight','btn-pantry-insight','admin-tasks-hint','profile-upgrade-section','admin-members-tools'].forEach(id=>{const e=el(id);if(e)e.classList.remove('hidden');});
            if(!isBiz){const rT=el('req-title');if(rT)rT.innerHTML='<i class="fa-solid fa-hourglass-half"></i> ממתינים לאישור';}
            const pU=el('profile-upgrade-section');if(pU&&currentGroup.is_premium)pU.innerHTML=`<p class="text-sm font-bold text-green-600 text-center py-2 flex items-center justify-center gap-2"><i class="fa-solid fa-check-circle"></i> ${isBiz?'ארגון משודרג':'חשבון משודרג'}</p>`;
        } else {
            ['btn-self-task','bank-child-view','academy-user-view'].forEach(id=>{const e=el(id);if(e)e.classList.remove('hidden');});
            const pU=el('profile-upgrade-section');if(pU)pU.classList.add('hidden');
            const cN=el('card-name'), cA=el('card-allowance'), cI=el('card-interest'), rT=el('req-title');
            if(cN)cN.innerText=(currentUser.nickname||'').toUpperCase(); if(cA)cA.innerText=`₪${currentUser.allowance_amount||0}`; if(cI)cI.innerText=`${currentUser.interest_rate||0}%`;
            if(rT)rT.innerHTML=isBiz?'<i class="fa-solid fa-hourglass-half"></i> בקשות רכש שלי':'<i class="fa-solid fa-hourglass-half"></i> בקשות שלי';
        }
        
        const bc=el('btn-add-budget-cat');if(bc)bc.classList.remove('hidden'); updateBatteryUI();
        if (isBiz && !isAdm) checkPunchStatus();
        
        try {
            await fetchBanners(); await fetchMembers(); await fetchData(); fetchLoans(); if(isAdm) fetchPendingUsers();
            if(!pollInterval) pollInterval=setInterval(()=>{fetchData();fetchLoans();if(isAdm)fetchPendingUsers();}, 30000);
        } catch(e){console.error('Fetch Data Error',e);showToast('error','שגיאה בטעינה');}
    } catch(e) { console.error('Dashboard Error', e); }
    finally {
        const p=el('app-preloader');
        const fin=async()=>{const sw=await checkGlobalWelcome();if(!sw){checkAndStartTour(forceTourStart);forceTourStart=false;}};
        if(p&&!p.classList.contains('hidden')){p.classList.add('opacity-0','pointer-events-none');setTimeout(()=>{p.classList.add('hidden');fin();},700);}else fin();
    }
}

async function fetchData() {
    try {
        if(!currentGroup||!currentGroup.id)return; if(document.activeElement&&document.activeElement.classList.contains('price-input'))return;
        const res=await fetch(`${API}/data/${currentUser.id}`); const data=await res.json(); if(!data||!data.user)return;
        
        currentUser.balance=data.user.balance;
        if(data.group){currentGroup.ai_tokens=data.group.ai_tokens;currentGroup.is_premium=data.group.is_premium;updateBatteryUI();}
        
        const ub=el('user-balance');if(ub)ub.innerText=`₪${currentUser.role==='ADMIN'?membersCache.filter(m=>m.role==='ADMIN').reduce((s,m)=>s+(parseFloat(m.balance)||0),0):(currentUser.balance||0)}`;
        
        allTasks=Array.isArray(data.tasks)?data.tasks:[];bundlesCache=Array.isArray(data.quiz_bundles)?data.quiz_bundles:[];pantryCache=Array.isArray(data.pantry)?data.pantry:[];if(data.all_bundles)allBundles=data.all_bundles;
        
        if(currentUser.role==='ADMIN')renderAdminAcademy();else{renderMyAssignments(bundlesCache);renderLibrary();}
        renderTasks(allTasks);renderPantry();renderRecipePantrySelection();
        shoppingListCache=Array.isArray(data.shopping_list)?data.shopping_list:[];renderShopList();
        fetchBudget();renderForecast();
        
        const gL=el(currentUser.role==='ADMIN'?'admin-goals-list':'my-goals-list'), gC=currentUser.role!=='ADMIN'?el('my-goals-container'):null;
        if(gL){gL.innerHTML='';if(data.goals&&data.goals.length>0){if(gC)gC.classList.remove('hidden');data.goals.forEach(g=>{const pt=Math.min(100,Math.round((g.current_amount/g.target_amount)*100));const b=currentUser.role==='ADMIN'?`<span class="text-[10px] bg-slate-100 px-2 py-0.5 rounded block mb-1">${g.owner_name}</span>`:'';const btn=currentGroup.type==='BUSINESS'?'העבר תקציב':'הפקד';gL.innerHTML+=`<div class="bg-white p-4 rounded-2xl shadow-sm border border-slate-50 flex items-start gap-4 mb-2"><div class="radial-progress shrink-0 mt-1" style="--pct:${pt*3.6}deg"><span>${pt}%</span></div><div class="flex-1">${b}<h4 class="font-bold text-slate-800">${g.title}</h4><p class="text-xs text-slate-500 mb-1">₪${g.current_amount} / ₪${g.target_amount}</p><div class="flex gap-2"><button onclick="openDepositModal(${g.id},'${g.title}')" class="mt-2 bg-indigo-50 text-indigo-600 px-3 py-1 rounded text-xs font-bold"><i class="fa-solid fa-plus"></i> ${btn}</button><button onclick="getFamilAIAdvice(${g.target_user_id||g.user_id},${g.id})" class="mt-2 text-[10px] text-purple-600 bg-purple-50 px-2 py-1 rounded border border-purple-100">טיפ AI</button></div></div></div>`;});}else{if(gC)gC.classList.add('hidden');gL.innerHTML='<p class="text-center text-slate-400 py-4">אין יעדים</p>';}}
        
        if(currentUser.role!=='ADMIN'&&data.weekly_stats){const sp=parseFloat(data.weekly_stats.spent).toFixed(1),lm=parseFloat(data.weekly_stats.limit).toFixed(1),pt=lm>0?(sp/lm)*100:0;const sE=el('card-spend-status'),bE=el('card-spend-bar'),mE=el('card-spend-msg');if(sE)sE.innerText=`₪${sp} מתוך ₪${lm}`;if(bE){bE.style.width=`${Math.min(100,pt)}%`;bE.className=parseFloat(sp)>parseFloat(lm)?'bg-red-500 h-1.5 rounded-full':'bg-green-400 h-1.5 rounded-full';}if(mE)mE.innerText=parseFloat(sp)>parseFloat(lm)?'חריגה!':'עמידה ביעדים';}
        
        const qId=currentUser.role==='ADMIN'?'all':currentUser.id;const tR=await fetch(`${API}/transactions?groupId=${currentGroup.id}&userId=${qId}&limit=200`);if(tR.ok)allTransactions=await tR.json();
        renderChildTodo();buildAndRenderFeed();const tc=el('tab-cashflow');if(tc&&tc.classList.contains('tab-active'))renderCashflow();
    }catch(e){console.error(e);}
}

// --- שעון נוכחות ---
async function checkPunchStatus(){try{const r=await fetch(`${API}/timeclock/status?userId=${currentUser.id}`);currentPunchStatus=await r.json();updatePunchUI();}catch(e){const b=el('btn-punch');if(b){b.innerText='שגיאה';b.classList.remove('punch-pulse','punch-btn-in','punch-btn-out');b.classList.add('bg-slate-200','text-slate-400');}}}
function updatePunchUI(){const b=el('btn-punch'),ic=el('punch-icon'),tx=el('punch-text'),st=el('timeclock-status-text');if(!b||!currentPunchStatus)return;b.classList.remove('bg-slate-200','text-slate-400','cursor-not-allowed','punch-btn-in','punch-btn-out','punch-pulse');if(currentPunchStatus.isPunchedIn){b.classList.add('punch-btn-out','punch-pulse');if(ic)ic.className='fa-solid fa-door-open text-4xl mb-1';if(tx)tx.innerText='יציאה';const t=new Date(currentPunchStatus.punchInTime).toLocaleTimeString('he-IL',{hour:'2-digit',minute:'2-digit'});if(st)st.innerHTML=`בעבודה. <span class="text-xs font-normal">כניסה: ${t}</span>`;}else{b.classList.add('punch-btn-in');if(ic)ic.className='fa-solid fa-fingerprint text-4xl mb-1';if(tx)tx.innerText='כניסה';if(st)st.innerHTML='לא בעבודה.';}}
async function togglePunch(){const b=el('btn-punch');if(b&&b.classList.contains('cursor-not-allowed'))return;if(b)b.classList.add('cursor-not-allowed','opacity-70');try{const r=await fetch(`${API}/timeclock/punch`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:currentUser.id,groupId:currentGroup.id})});const d=await r.json();if(d.success){triggerConfetti();showToast('success',d.isPunchedIn?'החתמת כניסה!':'החתמת יציאה.');checkPunchStatus();fetchTimeclockReport();}else showToast('error',d.error);}catch(e){showToast('error','שגיאה');}finally{if(b)b.classList.remove('cursor-not-allowed','opacity-70');}}
async function fetchTimeclockReport(){try{const df=el('tc-date-filter'),uf=el('tc-user-filter');const p=df?df.value:'month',tU=currentUser.role==='ADMIN'?(uf?uf.value:'all'):currentUser.id;const r=await fetch(`${API}/timeclock/report?groupId=${currentGroup.id}&userId=${tU}&period=${p}`);const d=await r.json();const lst=el('timeclock-list'),tot=el('tc-total-hours');if(!lst||!tot)return;let tm=0,h='';if(d.length===0){lst.innerHTML='<p class="text-center text-slate-400 py-4">אין דיווחים</p>';tot.innerText='00:00';return;}d.forEach(x=>{const iD=new Date(x.punch_in);let oS='--:--',dur='פעיל',b='<span class="text-[9px] bg-green-100 text-green-600 px-2 rounded">פעיל</span>';if(x.punch_out){const oD=new Date(x.punch_out);oS=oD.toLocaleTimeString('he-IL',{hour:'2-digit',minute:'2-digit'});if(x.total_minutes){tm+=parseInt(x.total_minutes);dur=`${String(Math.floor(x.total_minutes/60)).padStart(2,'0')}:${String(x.total_minutes%60).padStart(2,'0')} ש'`;}b='';}const uN=(currentUser.role==='ADMIN'&&x.nickname)?`<span class="text-[10px] text-indigo-600 bg-indigo-50 px-1 rounded ml-2">${x.nickname}</span>`:'';h+=`<div class="bg-white p-3 rounded-xl border shadow-sm mb-2 flex justify-between"><div class="flex-1"><div class="flex items-center mb-1"><span class="font-bold text-sm">${iD.toLocaleDateString('he-IL')}</span>${uN}${b}</div><div class="text-xs text-slate-500 font-mono"><span class="text-green-600">${iD.toLocaleTimeString('he-IL',{hour:'2-digit',minute:'2-digit'})}</span> <i class="fa-solid fa-arrow-left text-[8px] mx-1"></i> <span class="text-red-500">${oS}</span></div></div><div class="text-sm font-bold bg-slate-50 border px-3 py-1.5 rounded-lg">${dur}</div></div>`;});lst.innerHTML=h;tot.innerText=`${String(Math.floor(tm/60)).padStart(2,'0')}:${String(tm%60).padStart(2,'0')}`;}catch(e){}}

// --- חברים ואדמין ---
async function fetchMembers(){try{if(!currentGroup||!currentGroup.id)return;const r=await fetch(`${API}/group/members?groupId=${currentGroup.id}&requesterId=${currentUser.id}`);membersCache=await r.json();if(!Array.isArray(membersCache))membersCache=[];if(currentUser.role==='ADMIN'){const isB=currentGroup.type==='BUSINESS',tl=isB?'כל הצוות':'כל המשפחה';const uf=(i)=>{const e=el(i);if(e){const v=e.value;e.innerHTML=`<option value="all">${i==='budget-filter'?'כללי':tl}</option>`;membersCache.forEach(m=>e.innerHTML+=`<option value="${m.id}">${m.nickname}</option>`);if(v)e.value=v;if(i==='tc-user-filter')e.classList.remove('hidden');}};['budget-filter','feed-user-filter','cashflow-user-filter','tc-user-filter'].forEach(uf);const gS=el('goal-target-user');if(gS){const v=gS.value;gS.innerHTML='<option value="">עבור מי? (כללי)</option>';membersCache.filter(m=>m.role!=='ADMIN').forEach(m=>gS.innerHTML+=`<option value="${m.id}">${m.nickname}</option>`);if(v)gS.value=v;}}const ml=el('members-list');if(ml){ml.innerHTML='';membersCache.forEach(m=>{const i=m.nickname?m.nickname.charAt(0).toUpperCase():'?';const db=(currentUser.role==='ADMIN'&&m.id!==currentUser.id)?`<button onclick="deleteUser(${m.id},'${m.nickname}')" class="mr-3 text-red-400 bg-red-50 w-7 h-7 rounded-full"><i class="fa-solid fa-trash text-xs"></i></button>`:'';ml.innerHTML+=`<div class="p-3 flex justify-between items-center border-b border-slate-50"><div class="flex items-center gap-3"><div class="w-9 h-9 bg-slate-100 rounded-full flex items-center justify-center font-bold text-slate-500 shadow-sm">${i}</div><span class="font-bold text-sm">${m.nickname||''}</span></div><div class="flex items-center"><span class="text-xs font-bold text-slate-400 bg-slate-50 px-2 py-1 rounded-lg">${m.balance!==null?`₪${m.balance}`:'🔒'}</span>${db}</div></div>`;});}const al=el('bank-accounts-list');if(al&&currentUser.role==='ADMIN'){al.innerHTML='';const ch=membersCache.filter(m=>m.role!=='ADMIN');if(ch.length===0)al.innerHTML='<p class="text-center text-slate-400 py-4">אין משתמשים.</p>';else ch.forEach(m=>{const i=m.nickname?m.nickname.charAt(0).toUpperCase():'?';al.innerHTML+=`<div class="bg-white rounded-2xl p-4 shadow-sm border flex justify-between items-center mb-2"><div class="flex gap-3"><div class="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-full flex items-center justify-center font-bold">${i}</div><div><h4 class="font-bold text-sm">${m.nickname}</h4><p class="text-[10px] text-slate-400">₪${m.allowance_amount||0}/תקופה • ${m.interest_rate||0}%</p><p class="text-xs font-bold mt-1">יתרה: <span class="text-blue-600">₪${m.balance||0}</span></p></div></div><div class="flex gap-2"><button onclick="openBalanceAdjustmentModal(${m.id},'${m.nickname}')" class="w-8 h-8 rounded-full bg-blue-50 text-blue-500"><i class="fa-solid fa-money-bill-transfer"></i></button><button onclick="openBankSettings(${m.id},'${m.nickname}',${m.allowance_amount||0},${m.interest_rate||0})" class="w-8 h-8 rounded-full bg-slate-100 text-slate-500"><i class="fa-solid fa-gear"></i></button></div></div>`;});}}catch(e){}}
async function fetchPendingUsers() { try{if(!currentGroup||!currentGroup.id)return;const r=await fetch(`${API}/admin/pending-users?groupId=${currentGroup.id}`);const u=await r.json();const l=el('pending-list'),c=el('admin-panel');if(u&&u.length>0){if(c)c.classList.remove('hidden');if(l){l.innerHTML='';u.forEach(x=>{l.innerHTML+=`<div class="flex justify-between items-center bg-white p-2 rounded-xl mb-1 shadow-sm"><span class="text-sm font-bold">${x.nickname}</span><button onclick="approveUser(${x.id})" class="bg-green-500 text-white px-3 py-1 rounded-lg text-xs font-bold">אשר</button></div>`;});}}else{if(c)c.classList.add('hidden');}}catch(e){} }
