function buildAndRenderFeed() {
    feedCache=[];if(currentGroup&&currentGroup.created_at)feedCache.push({type:'system',id:'sys',user_id:0,user_name:'מערכת',date:new Date(currentGroup.created_at),title:'סביבת העבודה הוקמה בהצלחה! 🎉',amount:0});
    if(Array.isArray(allTransactions))allTransactions.forEach(t=>feedCache.push({type:'transaction',id:t.id,user_id:t.user_id,user_name:t.user_name||(currentUser?currentUser.nickname:''),date:t.date?new Date(t.date):new Date(),title:t.description,amount:t.amount,isIncome:t.type==='income',category:t.category}));
    if(Array.isArray(allTasks))allTasks.forEach(t=>{if(t.status==='approved')feedCache.push({type:'task',id:`t${t.id}`,user_id:t.assigned_to,user_name:t.assignee_name||'',date:t.created_at?new Date(t.created_at):new Date(),title:`משימה/טיקט: ${t.title}`,amount:t.reward,status:t.status});});
    if(Array.isArray(bundlesCache))bundlesCache.forEach(b=>{feedCache.push({type:'quiz',id:`q${b.bundle_id}`,user_id:b.user_id||b.assigned_to_user,user_name:b.assignee_name||'',date:b.assigned_at?new Date(b.assigned_at):(b.created_at?new Date(b.created_at):new Date()),title:`אתגר/חפיפה: ${b.title}`,amount:b.custom_reward!==null?b.custom_reward:b.default_reward,status:b.status});});
    feedCache.sort((a,b)=>(b.date&&a.date)?(b.date-a.date):0);const f=el('feed-user-filter');if(f&&currentUser)f.classList.toggle('hidden',currentUser.role!=='ADMIN');renderUnifiedFeed();
}
function renderUnifiedFeed() {
    const uf=val('feed-user-filter')||'all', df=val('feed-date-filter')||'all', lst=el('unified-feed-list');if(!lst)return;
    let f=feedCache;if(currentUser&&currentUser.role!=='ADMIN')f=f.filter(i=>String(i.user_id)===String(currentUser.id)||i.type==='system');else if(uf!=='all'&&uf!=='')f=f.filter(i=>String(i.user_id)===String(uf)||i.type==='system');
    if(df!=='all'){const c=new Date();c.setMonth(c.getMonth()-parseInt(df));f=f.filter(i=>i.date&&i.date>=c);} f=f.slice(0,30);
    if(f.length===0){lst.innerHTML='<div class="text-center py-10 bg-white rounded-3xl border"><p class="text-slate-400">אין פעילות</p></div>';return;}
    let h='';f.forEach(i=>{if(!i.date)return;const cc=i.type==='system'?'bg-orange-50':(userColors[i.user_id%userColors.length]||'bg-white');const un=i.type!=='system'&&i.user_name?`<span class="text-xs font-bold text-slate-500 block">${i.user_name}</span>`:'';const d=i.date;const isT=d.getDate()===new Date().getDate()&&d.getMonth()===new Date().getMonth();const ds=isT?`היום, ${d.toLocaleTimeString('he-IL',{hour:'2-digit',minute:'2-digit'})}`:`${d.toLocaleDateString('he-IL')} ${d.toLocaleTimeString('he-IL',{hour:'2-digit',minute:'2-digit'})}`;let c='';
    if(i.type==='transaction')c=`<div class="flex justify-between items-center w-full"><div>${un}<p class="font-bold text-slate-800 flex items-center gap-2">${i.isIncome?'<i class="fa-solid fa-arrow-trend-up text-green-500"></i>':'<i class="fa-solid fa-arrow-trend-down text-red-500"></i>'} ${i.title}</p><p class="text-[10px] text-slate-400">${ds}</p></div><span class="font-bold ${i.isIncome?'text-green-600':'text-red-600'}" dir="ltr">${i.isIncome?'+':'-'}₪${i.amount}</span></div>`;
    else if(i.type==='task')c=`<div class="flex justify-between items-center w-full"><div>${un}<p class="font-bold text-slate-700 flex items-center gap-2"><i class="fa-solid fa-check text-blue-500"></i> ${i.title}</p><p class="text-[10px] text-slate-400">${ds}</p></div><span class="text-xs font-bold text-blue-600 bg-blue-50 px-2 py-1 rounded-lg">₪${i.amount}</span></div>`;
    else if(i.type==='quiz')c=`<div class="flex justify-between items-center w-full"><div>${un}<p class="font-bold text-slate-700 flex items-center gap-2"><i class="fa-solid fa-graduation-cap text-purple-500"></i> ${i.title}</p><p class="text-[10px] text-slate-400">${ds}</p></div><span class="text-xs font-bold text-purple-600 bg-purple-50 px-2 py-1 rounded-lg">₪${i.amount}</span></div>`;
    else c=`<div class="flex justify-between items-center w-full"><div><p class="font-bold text-slate-800 flex items-center gap-2"><i class="fa-solid fa-house text-orange-500"></i> ${i.title}</p><p class="text-[10px] text-slate-400">${ds}</p></div></div>`;
    h+=`<div class="${cc} p-3.5 rounded-2xl shadow-sm border mb-2 flex items-center">${c}</div>`;});lst.innerHTML=h;
}

