window.openBalanceAdjustmentModal=function(id,n){const a=el('adjustment-user-id'),b=el('adjustment-user-name');if(a)a.value=id;if(b)b.innerText=`עבור: ${n}`;const m=el('balance-adjustment-modal');if(m)m.classList.remove('hidden');};
window.submitBalanceAdjustment=async function(){const a=parseFloat(val('adjustment-amount'));if(!a||a<=0)return showToast('error','סכום לא תקין');try{const r=await fetch(`${API}/admin/adjust-balance`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({adminId:currentUser.id,groupId:currentGroup.id,childId:val('adjustment-user-id'),type:val('adjustment-type'),amount:a,reason:val('adjustment-reason')||'הפחתה/בונוס יזום'})});const d=await r.json();if(d.success){showToast('success','עודכן!');const m=el('balance-adjustment-modal');if(m)m.classList.add('hidden');fetchData();fetchMembers();}else showToast('error',d.error);}catch(e){showToast('error','שגיאה');}};
