function openTransactionModal(t){const ty=el('trans-type'),tt=el('trans-modal-title'),tc=el('trans-cat');if(ty)ty.value=t;if(tt)tt.innerText=t==='income'?'הכנסה':'הוצאה';if(tc){tc.innerHTML='';CATEGORIES[t].forEach(c=>tc.innerHTML+=`<option value="${c.value}">${c.label}</option>`);}const td=el('trans-date');if(td)td.value=new Date().toISOString().split('T')[0];window.toggleTransType('onetime');const tm=el('transaction-modal');if(tm)tm.classList.remove('hidden');}
window.toggleTransType=function(type){const ir=type==='recurring';const tr=el('trans-is-recurring');if(tr)tr.value=ir;const on=document.body.classList.contains('is-business')?'bg-white text-slate-800':'bg-white text-blue-600',off=document.body.classList.contains('is-business')?'text-slate-500 hover:text-slate-800':'text-slate-500 hover:text-slate-700';const b1=el('btn-trans-onetime'),b2=el('btn-trans-recurring');if(b1)b1.className=ir?`flex-1 py-1.5 text-sm font-bold ${off} rounded-lg transition`:`flex-1 py-1.5 text-sm font-bold ${on} rounded-lg shadow-sm transition`;if(b2)b2.className=ir?`flex-1 py-1.5 text-sm font-bold ${on} rounded-lg shadow-sm transition`:`flex-1 py-1.5 text-sm font-bold ${off} rounded-lg transition`;const ed=el('trans-end-date-container'),em=el('trans-end-month');if(ir){if(ed)ed.classList.remove('hidden');}else{if(ed)ed.classList.add('hidden');if(em)em.value='';}};
async function submitTransaction(){const a=val('trans-amount');if(!a)return;if(val('trans-type')==='expense')triggerShake();else triggerConfetti();const ir=val('trans-is-recurring')==='true';let td=val('trans-date');if(!td)td=new Date().toISOString().split('T')[0];await fetch(`${API}/transaction`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:currentUser.id,amount:a,description:val('trans-desc')||'פעולה',category:val('trans-cat'),type:val('trans-type'),date:td,isRecurring:ir,endMonth:ir?val('trans-end-month'):null})});const m=el('transaction-modal');if(m)m.classList.add('hidden');showToast('success','נשמר!');fetchData();}
function openEditTransactionModal(id,a,d,c,t){const eI=el('edit-trans-id'),eO=el('edit-trans-old-amount'),eT=el('edit-trans-type'),eA=el('edit-trans-amount'),eD=el('edit-trans-desc'),eC=el('edit-trans-cat');if(eI)eI.value=id;if(eO)eO.value=a;if(eT)eT.value=t;if(eA)eA.value=a;if(eD)eD.value=d;if(eC){eC.innerHTML='';if(CATEGORIES[t]){CATEGORIES[t].forEach(cat=>{eC.innerHTML+=`<option value="${cat.value}" ${cat.value===c?'selected':''}>${cat.label}</option>`;});}else{eC.innerHTML+=`<option value="${c}" selected>${c}</option>`;}}const m=el('edit-transaction-modal');if(m)m.classList.remove('hidden');}
async function submitEditTransaction(){const a=val('edit-trans-amount');if(!a)return showToast('error','נא להזין סכום');const b=document.querySelector('#edit-transaction-modal button.bg-blue-600')||document.querySelector('#edit-transaction-modal button.bg-slate-800');const ot=b?b.innerText:'';if(b){b.disabled=true;b.innerText='שומר...';}try{const r=await fetch(`${API}/transaction/${val('edit-trans-id')}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({amount:a,description:val('edit-trans-desc'),category:val('edit-trans-cat'),requesterId:currentUser.id})});const d=await r.json();if(d.success){showToast('success','עודכן!');const m=el('edit-transaction-modal');if(m)m.classList.add('hidden');fetchData();}else showToast('error',d.error);}catch(e){showToast('error','שגיאה');}finally{if(b){b.disabled=false;b.innerText=ot;}}}
