function renderLoans(loans){if(currentUser.role==='ADMIN'){const p=el('admin-loans-panel'),l=el('admin-loans-list');if(!p||!l)return;const pe=loans.filter(x=>x.status==='pending');if(pe.length===0){p.classList.add('hidden');return;}p.classList.remove('hidden');l.innerHTML=pe.map(x=>`<div class="bg-white p-3 rounded-xl border border-slate-100 shadow-sm flex justify-between items-center mb-2"><div><p class="font-bold text-sm">${x.nickname} – ₪${x.original_amount}</p><p class="text-xs text-slate-500">${x.reason||'ללא'}</p></div><div class="flex gap-2"><button onclick="approveLoan(${x.id})" class="bg-green-500 text-white px-3 py-1.5 rounded-xl text-xs font-bold shadow-md">אשר</button><button onclick="rejectLoan(${x.id})" class="bg-red-100 text-red-600 px-3 py-1.5 rounded-xl text-xs font-bold">דחה</button></div></div>`).join('');}else{const l=el('my-loans-list');if(!l)return;if(!loans||loans.length===0){l.innerHTML='<p class="text-center text-slate-400 text-xs py-3">אין בקשות פתוחות</p>';return;}l.innerHTML=loans.map(x=>{const sm={pending:{l:'ממתין',c:'bg-orange-100 text-orange-600'},approved:{l:'אושרה ✓',c:'bg-green-100 text-green-700'},rejected:{l:'נדחתה',c:'bg-red-100 text-red-600'}};const s=sm[x.status]||{l:x.status,c:'bg-slate-100'};return `<div class="bg-white p-3 rounded-xl border shadow-sm flex justify-between mb-2"><div><p class="font-bold text-sm">₪${x.original_amount}</p><p class="text-xs text-slate-500">${x.reason||''} • ${new Date(x.created_at).toLocaleDateString('he-IL')}</p></div><span class="text-xs font-bold px-2 py-1 rounded-lg ${s.c}">${s.l}</span></div>`;}).join('');}}

