function applyBannersToDOM(b){const aT=el('app-banner-top'),aB=el('app-banner-bottom');const rb=(e,t,l,i)=>{if(!e)return;if(t||i){let h='';if(i)h+=`<img src="/${i}" class="w-full object-cover block">`;if(t)h+=`<span class="py-3 px-4 block w-full text-center">${t}</span>`;e.innerHTML=h;e.href=l||'#';if(l){e.target='_blank';e.style.cursor='pointer';}else{e.removeAttribute('target');e.style.cursor='default';}e.classList.remove('hidden');e.classList.add('flex');}else{e.classList.add('hidden');e.classList.remove('flex');}};rb(aT,b.banner_top_text,b.banner_top_link,b.banner_top_img);rb(aB,b.banner_bottom_text,b.banner_bottom_link,b.banner_bottom_img);}
