function renderChildTodo(){
    const s=el('child-todo-section'),l=el('child-todo-list');if(!s||!l)return;if(currentUser.role==='ADMIN'){s.classList.add('hidden');return;}
    let h='',c=false;const mt=allTasks.filter(t=>String(t.assigned_to)===String(currentUser.id)&&t.status==='pending');
    mt.forEach(t=>{c=true;let dM='';if(t.deadline){const d=Math.ceil((new Date(t.deadline)-new Date())/86400000);dM=d>0?` • <span class="text-orange-500">עוד ${d} ימים</span>`:` • <span class="text-red-500">פג תוקף!</span>`;}h+=`<div class="bg-white p-3 rounded-2xl border shadow-sm mb-2 flex justify-between items-center cursor-pointer" onclick="switchTab('tasks')"><div class="flex items-center gap-3"><div class="w-10 h-10 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center"><i class="fa-solid fa-list-check"></i></div><div><h4 class="font-bold text-sm">${t.title}</h4><p class="text-[10px] text-slate-500">${t.created_at?new Date(t.created_at).toLocaleDateString('he-IL'):''} • ₪${t.reward}${dM}</p></div></div><i class="fa-solid fa-chevron-left text-slate-300"></i></div>`;});
    const mq=bundlesCache.filter(b=>b.status==='assigned');
    mq.forEach(b=>{c=true;const r=b.custom_reward!==null?b.custom_reward:b.default_reward;let dM='';if(b.deadline){const d=Math.ceil((new Date(b.deadline)-new Date())/86400000);dM=d>0?` • <span class="text-orange-500">עוד ${d} ימים</span>`:` • <span class="text-red-500">פג תוקף!</span>`;}h+=`<div class="bg-white p-3 rounded-2xl border shadow-sm mb-2 flex justify-between items-center cursor-pointer" onclick="switchTab('academy')"><div class="flex items-center gap-3"><div class="w-10 h-10 bg-purple-100 text-purple-600 rounded-full flex items-center justify-center"><i class="fa-solid fa-graduation-cap"></i></div><div><h4 class="font-bold text-sm">${b.title}</h4><p class="text-[10px] text-slate-500">${b.assigned_at?new Date(b.assigned_at).toLocaleDateString('he-IL'):''} • ₪${r}${dM}</p></div></div><i class="fa-solid fa-chevron-left text-slate-300"></i></div>`;});
    if(c){l.innerHTML=h;s.classList.remove('hidden');}else{l.innerHTML='';s.classList.add('hidden');}
}

function renderTasks(ts){
    const l=el('tasks-list');if(!l)return;let h='',c=0;
    ts.forEach(t=>{const my=String(t.assigned_to)===String(currentUser.id),adm=currentUser.role==='ADMIN';if(!my&&!adm)return;c++;
    let cl='bg-white',bd='',btn='';
    if(t.status==='pending'){if(my)btn=`<button onclick="clickTaskProof(${t.id},'${t.title.replace(/'/g,"\\'")}')" class="bg-blue-600 text-white px-3 py-1.5 rounded-xl text-xs font-bold">סיימתי</button>`;else bd=`<span class="text-[10px] bg-slate-100 px-2 py-1 rounded">ממתין לביצוע</span>`;}
    else if(t.status==='done'){cl='bg-yellow-50';if(adm)btn=`<button onclick="openApproveTaskModal(${t.id},'${t.title.replace(/'/g,"\\'")}',${t.reward})" class="bg-green-500 text-white px-4 py-1.5 rounded-xl text-xs font-bold">אשר</button>`;else bd=`<span class="text-xs text-orange-500 bg-orange-50 px-2 py-1 rounded">בבדיקה</span>`;}
    else if(t.status==='approved'){cl='bg-green-50';bd=`<span class="text-xs text-green-600 font-bold"><i class="fa-solid fa-check"></i> בוצע</span>`;}
    const rD=t.reward>0?`<span class="text-xs font-bold text-blue-600 bg-blue-50 px-1.5 rounded">₪${t.reward}</span>`:`<span class="text-[10px] font-bold text-gray-500 bg-gray-100 px-1.5 rounded">ללא</span>`;
    let dl='';if(t.deadline&&t.status==='pending'){const df=Math.ceil((new Date(t.deadline)-new Date())/86400000);dl=df>0?`<span class="text-orange-500 bg-orange-50 px-1 py-0.5 rounded text-[9px] ml-2">עוד ${df} ימ'</span>`:`<span class="text-red-500 bg-red-50 px-1 py-0.5 rounded text-[9px] ml-2">פג תוקף!</span>`;}
    const ds=t.created_at?`<span class="text-[9px] text-slate-400 mr-2">${new Date(t.created_at).toLocaleDateString('he-IL')}</span>`:'';
    h+=`<div class="p-4 flex justify-between items-center mb-2 rounded-2xl border shadow-sm ${cl}"><div><p class="font-bold">${t.title} ${dl}</p><div class="flex items-center gap-2 mt-1"><span class="text-xs text-slate-500">${t.assignee_name}</span>${rD}${ds}</div></div><div class="flex flex-col items-end gap-1">${btn}${bd}</div></div>`;});
    if(c===0)l.innerHTML='<div class="text-center py-8 text-slate-400 text-sm">אין משימות פתוחות</div>';else l.innerHTML=h;
}

function openApproveTaskModal(id,ti,r){const i=el('approve-task-id'),t=el('approve-task-title'),rw=el('approve-task-reward'),m=el('approve-task-modal');if(i)i.value=id;if(t)t.innerText=ti;if(rw)rw.value=r||0;if(m)m.classList.remove('hidden');}
async function submitTaskApproval(){const id=val('approve-task-id'),r=val('approve-task-reward');const m=el('approve-task-modal');if(m)m.classList.add('hidden');triggerConfetti();await fetch(`${API}/tasks/update`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({taskId:id,status:'approved',finalReward:r})});showToast('success','המשימה אושרה!');fetchData();}
