function openTaskModal(s=false){const m=el('task-modal');if(m)m.classList.remove('hidden');const t=el('task-is-self');if(t)t.value=s;const mt=el('task-modal-title');if(mt)mt.innerText=s?'ביצוע טיקט/יעד':'יצירת משימה';setTaskMode('manual');const to=el('task-mode-toggles'),ac=el('task-assignee-container'),as=el('task-assignee'),tr=el('task-reward');if(s){if(to)to.classList.add('hidden');if(ac)ac.classList.add('hidden');if(tr)tr.placeholder='כמה מגיע לי? (₪)';}else{if(to)to.classList.remove('hidden');if(ac)ac.classList.remove('hidden');if(tr)tr.placeholder='תגמול (₪)';if(membersCache&&as){as.innerHTML='<option value="" disabled selected>בחרו...</option>';let hc=false;membersCache.forEach(m=>{if(m.role!=='ADMIN'){as.innerHTML+=`<option value="${m.id}">${m.nickname}</option>`;hc=true;}});if(!hc)as.innerHTML='<option value="" disabled selected>אין משתמשים</option>';}}}
function setTaskMode(m){const mb=el('btn-mode-manual'),ab=el('btn-mode-ai'),md=el('task-mode-manual'),ad=el('task-mode-ai');const on='flex-1 py-2 rounded-lg text-sm font-bold bg-white text-slate-800 shadow-sm transition',off='flex-1 py-2 rounded-lg text-sm font-bold text-slate-500 hover:text-slate-800 transition';if(m==='manual'){if(mb)mb.className=on;if(ab)ab.className=off;if(md)md.classList.remove('hidden');if(ad)ad.classList.add('hidden');}else{if(ab)ab.className=on;if(mb)mb.className=off;if(ad)ad.classList.remove('hidden');if(md)md.classList.add('hidden');}}
function closeTaskModal(){const m=el('task-modal');if(m)m.classList.add('hidden');}
async function submitTask(){const s=val('task-is-self')==='true',a=s?currentUser.id:val('task-assignee'),t=val('task-title'),r=val('task-reward'),d=val('task-days');if(!s&&!a)return showToast('error','יש לבחור משתמש');if(!t)return showToast('error','חובה להזין תיאור');await fetch(`${API}/tasks`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:t,reward:r||0,assignedTo:a,days:d,status:s?'done':'pending'})});if(s)triggerConfetti();closeTaskModal();showToast('success','נשמר!');fetchData();}
async function generateAITasks(){executeWithAIWarning(async()=>{const b=el('btn-ai-task-gen'),a=val('task-assignee'),t=val('ai-task-topic'),s=val('task-is-self')==='true';let age=18;if(s)age=new Date().getFullYear()-currentUser.birth_year;else{if(!a)return showToast('error','יש לבחור משתמש');const c=membersCache.find(x=>String(x.id)===String(a));if(c)age=new Date().getFullYear()-c.birth_year;}if(!t)return showToast('error','חסר נושא');if(b){b.disabled=true;b.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i>';}try{const r=await fetch(`${API}/tasks/ai-generate`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({age:age,topic:t,groupId:currentGroup.id})});const d=await r.json();if(!handleAIResponseCheck(d))return;if(d.success&&d.tasks){const rc=el('ai-task-results');if(rc){rc.innerHTML='<p class="text-xs text-slate-500 mb-2">בחרו משימה:</p>';d.tasks.forEach(x=>{rc.innerHTML+=`<div onclick="selectAITask('${(x.title||'').replace(/'/g,"\\'").replace(/"/g,"&quot;")}',${x.reward||0})" class="p-3 rounded-xl bg-white shadow-sm mb-2 cursor-pointer border hover:bg-slate-50 flex justify-between"><span class="text-sm font-bold">${x.title}</span><span class="text-xs bg-slate-100 px-2 rounded">₪${x.reward||0}</span></div>`;});rc.classList.remove('hidden');triggerConfetti();fetchData();}}else showToast('error','עמוס');}catch(e){showToast('error','שגיאה');}finally{if(b){b.disabled=false;b.innerHTML='חפש רעיונות';}}});}
function selectAITask(t,r){const ti=el('task-title'),rw=el('task-reward');if(ti)ti.value=t;if(rw)rw.value=r;setTaskMode('manual');}

function compressImage(f,mw,mh,q,cb){const r=new FileReader();r.onload=(e)=>{const i=new Image();i.onload=()=>{const c=document.createElement('canvas');let w=i.width,h=i.height;if(w>h){if(w>mw){h*=mw/w;w=mw;}}else{if(h>mh){w*=mh/h;h=mh;}}c.width=w;c.height=h;const ctx=c.getContext('2d');ctx.drawImage(i,0,0,w,h);cb(c.toDataURL('image/jpeg',q));};i.src=e.target.result;};r.readAsDataURL(f);}
function clickTaskProof(id,t){currentVerifyTaskId=id;currentVerifyTaskTitle=t;const u=el('task-proof-upload');if(u)u.click();}
function handleTaskProofUpload(e){const f=e.target.files[0];if(!f||!currentVerifyTaskId)return;executeWithAIWarning(()=>{showFamilAIModal('בקרת איכות',null);const fl=el('familai-loading-text');if(fl)fl.innerText='בודקת את הביצוע...';compressImage(f,800,800,0.7,async(d)=>{try{const res=await fetch(`${API}/tasks/vision-verify`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({taskId:currentVerifyTaskId,title:currentVerifyTaskTitle,imageBase64:d.split(',')[1],mimeType:'image/jpeg',groupId:currentGroup.id})});const j=await res.json();if(!handleAIResponseCheck(j)){const m=el('familai-advisor-modal');if(m)m.classList.add('hidden');return;}if(j.success){showFamilAIModal('בקרת איכות',j.message);if(j.verified){triggerConfetti();fetchData();}}else{const m=el('familai-advisor-modal');if(m)m.classList.add('hidden');showToast('error','שגיאה');}}catch(err){const m=el('familai-advisor-modal');if(m)m.classList.add('hidden');showToast('error','תקלה');}e.target.value='';});});}
function handleReceiptUpload(e){const f=e.target.files[0];if(!f)return;executeWithAIWarning(()=>{showFamilAIModal('סורק מסמכים',null);const fl=el('familai-loading-text');if(fl)fl.innerText='מפענחת את הקבלה...';compressImage(f,1200,1200,0.8,async(d)=>{try{const res=await fetch(`${API}/shopping/scan-receipt`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:currentUser.id,imageBase64:d.split(',')[1],mimeType:'image/jpeg'})});const j=await res.json();if(!handleAIResponseCheck(j)){const m=el('familai-advisor-modal');if(m)m.classList.add('hidden');return;}if(j.success){showFamilAIModal('סורק מסמכים',`נקלטו ${j.count} רשומות!`);triggerConfetti();fetchData();}else{const m=el('familai-advisor-modal');if(m)m.classList.add('hidden');showToast('error','שגיאה');}}catch(err){const m=el('familai-advisor-modal');if(m)m.classList.add('hidden');showToast('error','תקלה');}e.target.value='';});});}
function startBarcodeScan(t){currentScanTarget=t;let i=document.createElement('input');i.type='file';i.accept='image/*';i.capture='environment';i.onchange=(e)=>handleProductImageUpload(e,t);i.click();}
function handleProductImageUpload(e,t){const f=e.target.files[0];if(!f)return;executeWithAIWarning(()=>{showFamilAIModal('זיהוי אוטומטי',null);const fl=el('familai-loading-text');if(fl)fl.innerText='מפענחת תמונה...';compressImage(f,800,800,0.7,async(d)=>{try{const res=await fetch(`${API}/shopping/identify-product`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({imageBase64:d.split(',')[1],mimeType:'image/jpeg',groupId:currentGroup.id})});const j=await res.json();if(!handleAIResponseCheck(j)){const m=el('familai-advisor-modal');if(m)m.classList.add('hidden');return;}if(j.success&&j.productName){const m=el('familai-advisor-modal');if(m)m.classList.add('hidden');if(t==='shop'){const s=el('shop-item');if(s)s.value=j.productName;openShopModal();}else{const p=el('pantry-item');if(p)p.value=j.productName;openPantryModal();}showToast('success','זוהה בהצלחה!');}else{const m=el('familai-advisor-modal');if(m)m.classList.add('hidden');showToast('error','לא זוהה');}}catch(err){const m=el('familai-advisor-modal');if(m)m.classList.add('hidden');showToast('error','תקלה');}e.target.value='';});});}
