function renderAdminAcademy(){const l=el('admin-assignments-list');if(!l||!currentUser||currentUser.role!=='ADMIN')return;let h='<h4 class="font-bold text-slate-700 mt-2 mb-3">📚 ספריית מבחנים זמינה</h4>';if(!allBundles||allBundles.length===0){h+='<p class="text-sm text-slate-400 mb-6 bg-slate-50 p-4 rounded-xl text-center">אין מבחנים</p>';}else{h+='<div class="space-y-2 mb-8">';allBundles.forEach(b=>{const ic=b.type==='math'?'🔢':(b.type==='reading'?'📖':'📈');const dt=b.created_at?new Date(b.created_at).toLocaleDateString('he-IL'):'';h+=`<div class="bg-white p-3 rounded-xl border shadow-sm flex justify-between items-center"><div class="flex items-center gap-3"><div class="w-8 h-8 bg-blue-50 flex items-center justify-center">${ic}</div><div><h4 class="font-bold text-sm">${b.title}</h4><p class="text-[10px] text-slate-400">${dt} • התאמה: ${b.age_group} • פרס: ₪${b.reward}</p></div></div><button onclick="openAssignModalSpecific(${b.id})" class="bg-blue-50 text-blue-600 px-3 py-1.5 rounded-lg text-xs font-bold">הקצה</button></div>`;});h+='</div>';}h+='<h4 class="font-bold text-slate-700 mb-3 border-t border-slate-200 pt-6">🎯 הוקצו לאחרונה</h4>';if(!bundlesCache||bundlesCache.length===0){h+='<p class="text-sm text-slate-400 text-center bg-slate-50 p-4 rounded-xl">אין</p>';}else{h+='<div class="space-y-2 pb-20">';bundlesCache.forEach(b=>{const cl=b.status==='completed'?'text-green-500':(b.status==='failed'?'text-red-500':'text-orange-500');const tx=b.status==='completed'?'הושלם':(b.status==='failed'?'נכשל':'ממתין');const dt=b.assigned_at?new Date(b.assigned_at).toLocaleDateString('he-IL'):'';h+=`<div class="bg-white p-3 rounded-xl border shadow-sm flex justify-between items-center"><div><p class="font-bold text-sm">${b.title}</p><p class="text-[10px] text-slate-500 mt-0.5">הוקצה ל: ${b.assignee_name} ב-${dt}</p></div><span class="text-[10px] font-bold ${cl} bg-slate-50 px-2 py-1 rounded">${tx}</span></div>`;});h+='</div>';}l.innerHTML=h;}
function renderLibrary(){try{const l=el('library-list');if(!l)return;const af=val('lib-age-filter')||'all',cf=val('lib-cat-filter')||'all';let f=Array.isArray(allBundles)?[...allBundles]:[];if(af!=='all')f=f.filter(b=>b.age_group===af);if(cf!=='all')f=f.filter(b=>b.type===cf);if(Array.isArray(bundlesCache)){const as=bundlesCache.map(u=>Number(u.bundle_id));f=f.filter(b=>!as.includes(Number(b.id)));}if(f.length===0){l.innerHTML='<p class="text-center text-slate-400 text-xs py-4 bg-slate-50 rounded-xl">אין מבחנים להצגה</p>';return;}const gi=(t)=>t==='math'?'<i class="fa-solid fa-calculator"></i>':(t==='reading'?'<i class="fa-solid fa-book-open"></i>':'<i class="fa-solid fa-chart-line"></i>');let h='';f.forEach(b=>{const dt=b.created_at?new Date(b.created_at).toLocaleDateString('he-IL'):'';h+=`<div class="flex justify-between bg-white p-3 rounded-xl border shadow-sm mb-2"><div class="flex items-center gap-3"><div class="w-8 h-8 bg-blue-50 text-blue-600 flex items-center justify-center">${gi(b.type)}</div><div><h4 class="font-bold text-sm">${b.title}</h4><p class="text-[10px] text-slate-400">${dt} • גיל/רמה ${b.age_group} • ₪${b.reward}</p></div></div><button onclick="requestChallenge(${b.id})" class="bg-indigo-50 text-indigo-600 px-4 py-2 rounded-xl text-xs font-bold">התחל</button></div>`;});l.innerHTML=h;}catch(e){}}
async function requestChallenge(id=null){const b=document.querySelector('#academy-user-view button');if(b){b.disabled=true;b.innerText='מבקש...';}try{const r=await fetch(`${API}/academy/request-challenge`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:currentUser.id,bundleId:id})});const d=await r.json();if(d.success){triggerConfetti();showToast('success','נוסף!');fetchData();}else showToast('error',d.error);}catch(e){}finally{if(b){b.disabled=false;b.innerText='הגרל אקראי';}}}
function renderMyAssignments(as){const l=el('my-assignments-list'),hc=el('academy-history-container'),hl=el('academy-history-list');if(!l||!hc||!hl)return;l.innerHTML='';hl.innerHTML='';const p=as.filter(x=>x.status==='assigned'),h=as.filter(x=>x.status!=='assigned');if(p.length===0){l.innerHTML='<div class="text-center py-8 text-slate-400 text-sm">אין פתוחות</div>';}else{p.forEach(x=>{const r=x.custom_reward!==null?x.custom_reward:x.default_reward;let db='';if(x.deadline){const df=Math.ceil((new Date(x.deadline)-new Date())/86400000);db=df>0?`<span class="text-orange-500 bg-orange-50 px-1 py-0.5 rounded text-[9px] ml-2">עוד ${df} ימים</span>`:`<span class="text-red-500 bg-red-50 px-1 py-0.5 rounded text-[9px] ml-2">פג תוקף!</span>`;}l.innerHTML+=`<div class="bg-white p-4 rounded-2xl border shadow-sm flex justify-between mb-2"><div><p class="font-bold">${x.title} ${db}</p><p class="text-xs text-slate-500 mt-1">בונוס: ₪${r} (דרוש ${x.threshold}%)</p></div><button onclick="startQuiz(${x.bundle_id})" class="bg-indigo-600 text-white px-4 py-2 rounded-xl text-xs font-bold">התחל</button></div>`;});}if(h.length>0){hc.classList.remove('hidden');h.forEach(x=>{const r=x.custom_reward!==null?x.custom_reward:x.default_reward,ps=x.status==='completed',cc=ps?'text-green-500':'text-red-500',tl=ps?`עברת (${x.score}%)`:`נכשלת (${x.score}%)`,ic=ps?'🏆':'📚';hl.innerHTML+=`<div class="bg-white p-3 rounded-xl border opacity-80 flex justify-between mb-2"><div><p class="font-bold text-sm">${ic} ${x.title}</p><p class="text-[10px] text-slate-500">בונוס: ₪${r}</p></div><span class="text-xs font-bold ${cc} bg-slate-50 px-2 py-1 rounded">${tl}</span></div>`;});}else{hc.classList.add('hidden');}}

async function startQuiz(id){const b=bundlesCache.find(x=>x.bundle_id==id);if(!b)return;currentQuizData=b;currentQuestionIndex=0;quizScore=0;currentWrongAnswers=[];const qt=el('quiz-title');if(qt)qt.innerText=b.title;const bt=el('btn-tutor');if(bt)bt.classList.add('hidden');const tc=el('quiz-text-container');if(tc){if(b.text_content){tc.innerHTML=`<p>${b.text_content}</p>`;tc.classList.remove('hidden');}else{tc.classList.add('hidden');}}const m=el('quiz-runner-modal');if(m)m.classList.remove('hidden');renderQuestion();}
function renderQuestion(){const q=currentQuizData.questions[currentQuestionIndex],qp=el('q-progress'),qt=el('q-text'),oc=el('q-options');if(qp)qp.innerText=`${currentQuestionIndex+1} / ${currentQuizData.questions.length}`;if(qt)qt.innerText=q.q;if(!oc)return;oc.innerHTML='';q.options.forEach((o,i)=>{oc.innerHTML+=`<button onclick="submitAnswer(${i})" class="quiz-option w-full p-4 rounded-xl text-right bg-slate-50 font-medium hover:bg-slate-100 text-slate-700">${o}</button>`;});}
async function submitAnswer(ix){const q=currentQuizData.questions[currentQuestionIndex],ic=ix===q.correct,bs=document.querySelectorAll('.quiz-option');if(bs[ix])bs[ix].classList.add(ic?'correct':'wrong');if(!ic&&bs[q.correct]){bs[q.correct].classList.add('correct');currentWrongAnswers.push({q:q.q,wrong:q.options[ix],correct:q.options[q.correct]});}if(ic)quizScore++;setTimeout(async()=>{currentQuestionIndex++;if(currentQuestionIndex<currentQuizData.questions.length)renderQuestion();else finishQuiz();},1000);}
async function finishQuiz(){const t=currentQuizData.questions.length,fs=Math.round((quizScore/t)*100),p=fs>=currentQuizData.threshold;const qc=el('question-container'),qtc=el('quiz-text-container'),qr=el('quiz-result');if(qc)qc.classList.add('hidden');if(qtc)qtc.classList.add('hidden');if(qr)qr.classList.remove('hidden');const qi=el('quiz-icon');if(qi)qi.innerHTML=p?'🏆':'📚';const qmt=el('quiz-msg-title');if(qmt)qmt.innerText=p?'כל הכבוד!':'לא נורא...';const qmd=el('quiz-msg-desc');if(qmd)qmd.innerText=p?`עמדת ביעד וזכית ב-₪${currentQuizData.custom_reward||currentQuizData.default_reward}`:`צריך ${currentQuizData.threshold}% כדי לעבור`;const qsd=el('quiz-score-display');if(qsd)qsd.innerText=`ציון: ${fs}%`;if(!p&&currentWrongAnswers.length>0){const bt=el('btn-tutor');if(bt)bt.classList.remove('hidden');}if(p)triggerConfetti();await fetch(`${API}/academy/submit`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:currentUser.id,bundleId:currentQuizData.bundle_id,score:fs})});fetchData();}
function closeQuiz(){const m=el('quiz-runner-modal'),qc=el('question-container'),qr=el('quiz-result');if(m)m.classList.add('hidden');if(qc)qc.classList.remove('hidden');if(qr)qr.classList.add('hidden');}

function renderRecipePantrySelection(){const l=el('recipe-pantry-items-list');if(!l)return;l.innerHTML='';if(pantryCache.length===0){l.innerHTML='<p class="text-xs text-slate-400">המלאי ריק.</p>';return;}pantryCache.forEach(p=>{l.innerHTML+=`<label class="flex items-center gap-1 bg-slate-50 border px-2 py-1 rounded"><input type="checkbox" value="${p.item_name}" class="recipe-pantry-cb w-3 h-3"><span class="text-xs">${p.item_name}</span></label>`;});}
function toggleRecipeCustomInput(){const ig=el('recipe-ignore-pantry'),cI=el('recipe-custom-ingredients'),pS=el('recipe-pantry-selection');if(ig&&ig.checked){if(cI)cI.classList.remove('hidden');if(pS)pS.classList.add('opacity-50','pointer-events-none');}else{if(cI)cI.classList.add('hidden');if(pS)pS.classList.remove('opacity-50','pointer-events-none');}}
function selectAllRecipePantry(){const c=document.querySelectorAll('.recipe-pantry-cb');let a=true;c.forEach(x=>{if(!x.checked)a=false;});c.forEach(x=>x.checked=!a);}
async function generateRecipe(){const m=val('recipe-meal-type'),d=val('recipe-diners'),ig=el('recipe-ignore-pantry'),igv=ig?ig.checked:false,cI=val('recipe-custom-ingredients');let pI=[];document.querySelectorAll('.recipe-pantry-cb:checked').forEach(x=>pI.push(x.value));if(!igv&&pI.length===0)return showToast('error','בחר מוצרים');if(igv&&!cI)return showToast('error','הקלידו ידנית');const b=el('btn-generate-recipe');if(b){b.disabled=true;b.innerHTML='מעבד...';}try{const r=await fetch(`${API}/recipes/generate`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({groupId:currentGroup.id,mealType:m,diners:d,ignorePantry:igv,customIngredients:cI,pantryItems:pI.join(',')})});const dt=await r.json();if(!handleAIResponseCheck(dt))return;if(dt.success){const c=el('recipe-result-container'),ct=el('recipe-result-content');if(c&&ct){ct.innerHTML=dt.recipe.replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/\*(.*?)\*/g,'<em>$1</em>').replace(/\n/g,'<br>');c.classList.remove('hidden');c.scrollIntoView({behavior:'smooth'});triggerConfetti();}}else showToast('error','שגיאה');}catch(e){}finally{if(b){b.disabled=false;b.innerHTML='צור מתכון עכשיו';}}}
function copyRecipe(){const c=el('recipe-result-content');if(c){navigator.clipboard.writeText(c.innerText);showToast('success','הועתק!');}}

// --- FORECAST ---
window.toggleForecastMode=function(m){currentForecastMode=m;const bM=el('btn-forecast-monthly'),bY=el('btn-forecast-yearly');if(bM)bM.className=m==='monthly'?'flex-1 py-1.5 text-sm font-bold bg-white text-indigo-600 rounded-lg shadow-sm':'flex-1 py-1.5 text-sm font-bold text-slate-500 rounded-lg';if(bY)bY.className=m==='yearly'?'flex-1 py-1.5 text-sm font-bold bg-white text-indigo-600 rounded-lg shadow-sm':'flex-1 py-1.5 text-sm font-bold text-slate-500 rounded-lg';const fM=el('forecast-month-filter'),fY=el('forecast-year-filter');if(fM)fM.classList.toggle('hidden',m!=='monthly');if(fY)fY.classList.toggle('hidden',m!=='yearly');renderForecast();};
function populateForecastPeriods(){const m=el('forecast-month-filter'),y=el('forecast-year-filter');if(m&&m.options.length===0){const n=new Date();for(let i=0;i<12;i++){const d=new Date(n.getFullYear(),n.getMonth()+i,1);m.innerHTML+=`<option value="${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}">${d.toLocaleDateString('he-IL',{month:'long',year:'numeric'})}</option>`;}}if(y&&y.options.length===0){const c=new Date().getFullYear();for(let i=0;i<5;i++){y.innerHTML+=`<option value="${c+i}">שנת ${c+i}</option>`;}}}
async function renderForecast(){populateForecastPeriods();const l=el('forecast-list');if(!l||!currentGroup||!currentGroup.id)return;const t=currentUser.role==='ADMIN'?'all':currentUser.id;const pV=currentForecastMode==='monthly'?val('forecast-month-filter'):val('forecast-year-filter');let sD,eD;if(currentForecastMode==='monthly'){if(!pV){const n=new Date();sD=new Date(n.getFullYear(),n.getMonth(),1);eD=new Date(n.getFullYear(),n.getMonth()+1,0,23,59,59);}else{const[y,m]=pV.split('-');sD=new Date(y,parseInt(m)-1,1);eD=new Date(y,parseInt(m),0,23,59,59);}}else{const y=pV?parseInt(pV):new Date().getFullYear();sD=new Date(y,0,1);eD=new Date(y,11,31,23,59,59);}let sB=0;if(t==='all'){sB=membersCache.reduce((s,m)=>s+(parseFloat(m.balance)||0),0);}else{const u=membersCache.find(x=>String(x.id)===String(t));if(u)sB=parseFloat(u.balance)||0;}const it=[];const tx=t!=='all'?allTransactions.filter(x=>String(x.user_id)===String(t)):allTransactions;tx.forEach(x=>{const d=new Date(x.date),a=parseFloat(x.amount),ir=x.is_recurring===true||String(x.is_recurring).toLowerCase()==='true';if(!ir){if(d>=sD&&d<=eD)it.push({...x,amount:a,date_str:d.toLocaleDateString('he-IL')});}else{let tSM=new Date(d.getFullYear(),d.getMonth(),1);let vE=true,enD=null;if(x.end_month){const[ey,em]=x.end_month.split('-');enD=new Date(ey,parseInt(em),0,23,59,59);if(sD>enD)vE=false;}if(eD<tSM)vE=false;if(vE){if(currentForecastMode==='monthly'){it.push({...x,amount:a,date_str:'קבוע (חודשי)'});}else if(currentForecastMode==='yearly'){let mA=0;for(let i=0;i<12;i++){let cS=new Date(sD.getFullYear(),i,1),cE=new Date(sD.getFullYear(),i+1,0,23,59,59);let iA=cS>=tSM;if(enD&&cE>enD)iA=false;if(iA)mA++;}if(mA>0)it.push({...x,amount:a*mA,description:`${x.description} (x${mA} ח')`,date_str:'קבוע (שנתי)'});}}}});forecastCache={startingBalance:sB,items:it};const iR=forecastCache.items||[];let tI=0,tE=0,pNC=0;const iD={},eDta={};let h='';const n=new Date();if(iR.length===0){h='<p class="text-center text-slate-400 py-8">אין פעולות בתקופה זו</p>';}else{iR.forEach(x=>{const ii=x.type==='income',a=parseFloat(x.amount),dt=new Date(x.date),ir=x.is_recurring===true||String(x.is_recurring).toLowerCase()==='true';if(ii){tI+=a;iD[x.category]=(iD[x.category]||0)+a;}else{tE+=a;eDta[x.category]=(eDta[x.category]||0)+a;}if(ir||dt>n){if(ii)pNC+=a;else pNC-=a;}const ic=ii?'<i class="fa-solid fa-arrow-trend-up text-green-500"></i>':'<i class="fa-solid fa-arrow-trend-down text-red-500"></i>';const aC=ii?'text-green-600':'text-red-600',px=ii?'+':'-',rb=ir?'<span class="text-[9px] bg-indigo-50 text-indigo-600 px-1 rounded ml-2">קבועה</span>':'',uN=currentUser.role==='ADMIN'&&x.user_name?`<span class="text-[9px] bg-slate-100 px-1 rounded ml-1">${x.user_name}</span>`:'';h+=`<div class="bg-white p-3 rounded-2xl border mb-2 flex justify-between"><div class="flex-1"><p class="font-bold flex items-center">${ic} <span class="mr-2 truncate">${x.description}</span> ${uN} ${rb}</p><p class="text-[10px] text-slate-400">${x.date_str}</p></div><span class="font-bold ${aC}" dir="ltr">${px}₪${x.amount}</span></div>`;});}l.innerHTML=h;const pB=sB+pNC;const fNC=el('forecast-net-change');if(fNC){fNC.innerText=`₪${pNC.toFixed(2)}`;fNC.className=`text-lg font-bold ${pNC>=0?'text-green-600':'text-red-600'}`;}const fPB=el('forecast-projected-balance');if(fPB)fPB.innerText=`₪${pB.toFixed(2)}`;drawForecastCharts({income:tI},{expense:tE});}
function drawForecastCharts(iD,eD){const c=el('forecast-charts');if(!c)return;c.innerHTML=`<div class="w-full max-w-[250px]"><h4 class="text-sm font-bold text-center text-slate-600 mb-2">הכנסות מול הוצאות</h4><div class="relative h-48 flex justify-center"><canvas id="ratioChart"></canvas></div></div>`;const ctx=el('ratioChart');if(!ctx)return;if(forecastRatioChart)forecastRatioChart.destroy();const tI=Object.values(iD).reduce((a,b)=>a+b,0),tE=Object.values(eD).reduce((a,b)=>a+b,0);if(tI>0||tE>0){forecastRatioChart=new Chart(ctx,{type:'doughnut',data:{labels:['הכנסות','הוצאות'],datasets:[{data:[tI,tE],backgroundColor:['#22c55e','#ef4444']}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'}}}});}else{c.innerHTML='<p class="text-center text-slate-400 text-xs py-4">אין תנועות</p>';}}
function getForecastInsight(){executeWithAIWarning(async()=>{showFamilAIModal('תובנות עתיד',null);const l=el('familai-loading-text');if(l)l.innerText='מחשבת תזרים...';try{const pV=currentForecastMode==='monthly'?val('forecast-month-filter'):val('forecast-year-filter'),tU=currentUser.role==='ADMIN'?'all':currentUser.id;const r=await fetch(`${API}/forecast/familai-insight`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({groupId:currentGroup.id,period:pV,mode:currentForecastMode,targetUserId:tU})});const d=await r.json();if(!handleAIResponseCheck(d)){const m=el('familai-advisor-modal');if(m)m.classList.add('hidden');return;}if(d.success&&d.insight)showFamilAIModal('תובנות תזרים',d.insight);else{const m=el('familai-advisor-modal');if(m)m.classList.add('hidden');showToast('error','שגיאה');}}catch(e){const m=el('familai-advisor-modal');if(m)m.classList.add('hidden');showToast('error','שגיאה');}});}
